//! Network-specific circuit constraints generated by OCaml 4.0.2.
//!
//! Native builds with `embedded-circuits` read Mesa devnet and mainnet
//! gates, internal variables and row mappings from embedded zstd frames.
//! Every frame is decompressed and SHA-256 checked before use. A decode or
//! digest error is terminal; it cannot fall through to another source.
//!
//! Without an embedded entry, native builds search
//! `MINA_CIRCUIT_BLOBS_BASE_DIR`, the crate directory, the home circuit cache
//! and `/usr/local/lib/mina/circuit-blobs`, in that order. Mainnet files must
//! match the pinned manifest even when embedding is disabled. Missing or
//! unlisted mainnet files are errors; mainnet circuit downloads are disabled.
//! Other network paths retain the GitHub release fallback.
//!
//! Generate either set with `tools/mesa-circuits/generate.sh` and embed it
//! with `tools/mesa-circuits/embed.py --network mainnet|devnet <source>`.
//! The manifests are `tools/mesa-circuits/{mainnet,devnet}-blobs.sha256`.
//! Network selection comes from `mina_core::network::CircuitsConfig`.
//!
//! WASM checks hosted prover files against the same canonical manifests,
//! plus mandatory build pins, on both same-origin and external asset hosts.
//! Verifier index caches use the separate local-only [`read_local`] path.

use std::path::Path;

#[cfg(not(target_family = "wasm"))]
#[path = "embedded_circuits.rs"]
mod embedded_circuits;

#[cfg(not(target_family = "wasm"))]
fn circuit_path(filename: &Path) -> Option<(&str, &str)> {
    use std::path::Component;

    let mut parts = filename.components().filter(|p| *p != Component::CurDir);
    let (Component::Normal(directory), Component::Normal(name)) = (parts.next()?, parts.next()?)
    else {
        return None;
    };
    if parts.next().is_some() {
        return None;
    }
    Some((directory.to_str()?, name.to_str()?))
}

/// Mainnet never accepts an unpinned circuit, including feature-off builds.
/// The caller supplies the network directory from `CircuitsConfig`.
#[cfg(not(target_family = "wasm"))]
fn mainnet_pin(filename: &Path) -> std::io::Result<Option<&'static str>> {
    use std::path::Component;

    if !filename
        .components()
        .any(|p| p == Component::Normal("4.0.2mainnet".as_ref()))
    {
        return Ok(None);
    }
    let canonical = circuit_path(filename)
        .map(|(directory, name)| format!("{directory}/{name}"))
        .and_then(|name| circuit_pins::canonical_pin(&name).ok().flatten());
    canonical.map(Some).ok_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!(
                "mainnet circuit {} has no pinned SHA-256",
                filename.display()
            ),
        )
    })
}

#[cfg(all(not(target_family = "wasm"), feature = "embedded-circuits"))]
fn decode_embedded(
    compressed: &[u8],
    name: &str,
    expected_sha256: &str,
) -> std::io::Result<Vec<u8>> {
    use std::io::Read;

    let mut bytes = Vec::new();
    ruzstd::decoding::StreamingDecoder::new(compressed)
        .map_err(std::io::Error::other)?
        .read_to_end(&mut bytes)?;
    let pins =
        CircuitPins::parse(&format!("{name}={expected_sha256}")).map_err(std::io::Error::other)?;
    pins.check(name, &bytes)?;
    Ok(bytes)
}

#[cfg(all(not(target_family = "wasm"), feature = "embedded-circuits"))]
fn fetch_embedded(filename: &Path) -> Option<std::io::Result<Vec<u8>>> {
    let (directory, name) = circuit_path(filename)?;
    let circuit = embedded_circuits::get(directory, name)?;
    Some(decode_embedded(circuit.compressed, name, circuit.sha256))
}

#[path = "circuit_pins.rs"]
mod circuit_pins;
pub use circuit_pins::CircuitPins;

/// Missing or malformed build pins fail closed in both hosted-asset modes.
#[cfg(target_family = "wasm")]
fn compiled_pins() -> std::io::Result<&'static CircuitPins> {
    static PINS: std::sync::OnceLock<Result<CircuitPins, String>> = std::sync::OnceLock::new();
    PINS.get_or_init(|| CircuitPins::from_build(option_env!("CIRCUIT_BLOBS_SHA256")))
        .as_ref()
        .map_err(|error| std::io::Error::new(std::io::ErrorKind::InvalidData, error.clone()))
}

#[cfg(target_family = "wasm")]
fn checked(filename: &str, bytes: Vec<u8>) -> std::io::Result<Vec<u8>> {
    compiled_pins()?.check_hosted(filename, &bytes)?;
    Ok(bytes)
}

#[cfg(not(target_family = "wasm"))]
pub fn home_base_dir() -> Option<std::path::PathBuf> {
    let mut path = std::path::PathBuf::from(std::env::var("HOME").ok()?);
    path.push(".mina/circuit-blobs");
    Some(path)
}

#[cfg(all(test, not(target_family = "wasm")))]
thread_local! {
    static TEST_MISSING_CIRCUIT: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

#[cfg(all(test, not(target_family = "wasm")))]
pub(crate) fn with_missing_circuit<T>(f: impl FnOnce() -> T) -> T {
    TEST_MISSING_CIRCUIT.with(|missing| {
        let previous = missing.replace(true);
        let result = f();
        missing.set(previous);
        result
    })
}

fn git_release_url(filename: &impl AsRef<Path>) -> String {
    const RELEASES_PATH: &str = "https://github.com/o1-labs/circuit-blobs/releases/download";
    let filename_str = filename.as_ref().to_str().unwrap();

    format!("{RELEASES_PATH}/{filename_str}")
}

/// `filename` in the local sources, in their order: `MINA_CIRCUIT_BLOBS_BASE_DIR`,
/// this crate's directory, `~/.mina/circuit-blobs`, the system directory.
#[cfg(not(target_family = "wasm"))]
fn find_local(filename: &impl AsRef<Path>) -> Option<std::path::PathBuf> {
    fn try_base_dir<P: Into<std::path::PathBuf>>(
        base_dir: P,
        filename: &impl AsRef<Path>,
    ) -> Option<std::path::PathBuf> {
        let mut path = base_dir.into();
        path.push(filename);
        path.exists().then_some(path)
    }
    None.or_else(|| try_base_dir(std::env::var("MINA_CIRCUIT_BLOBS_BASE_DIR").ok()?, filename))
        .or_else(|| try_base_dir(env!("CARGO_MANIFEST_DIR").to_string(), filename))
        .or_else(|| try_base_dir(home_base_dir()?, filename))
        .or_else(|| try_base_dir("/usr/local/lib/mina/circuit-blobs", filename))
}

/// A file only the node writes, such as a verifier index cache, from the
/// local sources; never fetched (RC7-FIXES: no circuit-blobs release has the
/// caches, so a first start logged a 404 for each). [`std::io::ErrorKind::NotFound`]
/// if it isn't there.
#[cfg(not(target_family = "wasm"))]
pub fn read_local(filename: &impl AsRef<Path>) -> std::io::Result<Vec<u8>> {
    match find_local(filename) {
        Some(path) => std::fs::read(path),
        None => Err(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("{} is not cached", filename.as_ref().display()),
        )),
    }
}

#[cfg(not(target_family = "wasm"))]
pub fn fetch_blocking(filename: &impl AsRef<Path>) -> std::io::Result<Vec<u8>> {
    #[cfg(test)]
    if TEST_MISSING_CIRCUIT.with(|missing| missing.get()) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            "test circuit blob missing",
        ));
    }

    fetch_native(filename.as_ref(), || find_local(filename))
}

#[cfg(not(target_family = "wasm"))]
fn fetch_native(
    filename: &Path,
    local_source: impl FnOnce() -> Option<std::path::PathBuf>,
) -> std::io::Result<Vec<u8>> {
    let pinned = mainnet_pin(filename)?;
    #[cfg(feature = "embedded-circuits")]
    if let Some(result) = fetch_embedded(filename) {
        let bytes = result?;
        static LOGGED: std::sync::Once = std::sync::Once::new();
        LOGGED.call_once(|| {
            mina_core::info!(
                mina_core::log::system_time();
                kind = "ledger proofs",
                message = "circuit blobs served from embedded Mesa circuits",
                directory = circuit_path(filename).unwrap().0,
            );
            #[cfg(test)]
            eprintln!(
                "circuit source: embedded {} (no circuit file read or download)",
                circuit_path(filename).unwrap().0
            );
        });
        return Ok(bytes);
    }

    fn to_io_err(err: impl std::fmt::Display) -> std::io::Error {
        std::io::Error::other(format!(
            "circuit blob not found in local sources and GitHub fetch failed: {err}"
        ))
    }

    let home_base_dir = home_base_dir();
    if let Some(path) = local_source() {
        #[cfg(feature = "embedded-circuits")]
        {
            static LOGGED: std::sync::Once = std::sync::Once::new();
            LOGGED.call_once(|| {
                mina_core::info!(
                    mina_core::log::system_time();
                    kind = "ledger proofs",
                    message = "circuit blobs served from local files",
                )
            });
        }
        let bytes = std::fs::read(path)?;
        if let Some(digest) = pinned {
            let name = filename.to_string_lossy();
            CircuitPins::parse(&format!("{name}={digest}"))
                .map_err(std::io::Error::other)?
                .check(&name, &bytes)?;
        }
        return Ok(bytes);
    }

    if pinned.is_some() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!(
                "verified mainnet circuit {} is unavailable; enable embedded-circuits or install files matching tools/mesa-circuits/mainnet-blobs.sha256; mainnet circuit downloads are disabled",
                filename.display(),
            ),
        ));
    }

    mina_core::info!(
        mina_core::log::system_time();
        kind = "ledger proofs",
        message = "circuit-blobs not found locally, so fetching it...",
        filename = filename.to_str().unwrap(),
    );

    let base_dir = home_base_dir.ok_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::NotFound,
            "circuit blob not found in local sources; HOME is unset, so GitHub cannot be cached",
        )
    })?;

    // A missing file answers 404 with a body: without `error_for_status` that
    // body was returned and cached in place of the file, and kept failing
    // after a release appeared. Mainnet never reaches this download path.
    let bytes = reqwest::blocking::get(git_release_url(&filename))
        .and_then(|response| response.error_for_status())
        .map_err(to_io_err)?
        .bytes()
        .map_err(to_io_err)?
        .to_vec();

    #[cfg(feature = "embedded-circuits")]
    {
        static LOGGED: std::sync::Once = std::sync::Once::new();
        LOGGED.call_once(|| {
            mina_core::info!(
                mina_core::log::system_time();
                kind = "ledger proofs",
                message = "circuit blobs served from GitHub release",
            )
        });
    }

    // cache it to home dir.
    let cache_path = base_dir.join(filename);
    mina_core::info!(
        mina_core::log::system_time();
        kind = "ledger proofs",
        message = "caching circuit-blobs",
        path = cache_path.to_str().unwrap(),
    );
    let _ = std::fs::create_dir_all(cache_path.parent().unwrap());
    let _ = std::fs::write(cache_path, &bytes);

    Ok(bytes)
}

#[cfg(target_family = "wasm")]
pub async fn fetch(filename: &impl AsRef<Path>) -> std::io::Result<Vec<u8>> {
    let prefix =
        option_env!("CIRCUIT_BLOBS_HTTP_PREFIX").unwrap_or("/assets/webnode/circuit-blobs");
    let name = filename.as_ref().to_str().unwrap();
    let url = format!("{prefix}/{name}");
    checked(name, mina_core::http::get_bytes(&url).await?)
}

#[cfg(target_family = "wasm")]
pub fn fetch_blocking(filename: &impl AsRef<Path>) -> std::io::Result<Vec<u8>> {
    let prefix =
        option_env!("CIRCUIT_BLOBS_HTTP_PREFIX").unwrap_or("/assets/webnode/circuit-blobs");
    let name = filename.as_ref().to_str().unwrap();
    let url = format!("{prefix}/{name}");
    checked(name, mina_core::http::get_bytes_blocking(&url)?)
}

#[cfg(test)]
mod pin_tests {
    use super::CircuitPins;
    use sha2::{Digest, Sha256};

    const FILE: &str = "4.0.2devnet/block_verifier_index.postcard";

    fn hex_of(bytes: &[u8]) -> String {
        hex::encode(Sha256::digest(bytes))
    }

    #[test]
    fn pinned_bytes_pass_and_others_are_refused() {
        let pins = CircuitPins::parse(&format!("{FILE}={}", hex_of(b"cache"))).unwrap();
        pins.check(FILE, b"cache").unwrap();
        let err = pins.check(FILE, b"cachf").unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::InvalidData);
        assert!(err.to_string().contains("refused"), "{err}");
        assert!(err.to_string().contains(&hex_of(b"cache")), "{err}");
    }

    #[test]
    fn a_file_without_a_pin_is_refused() {
        let pins = CircuitPins::parse(&format!("{FILE}={}", hex_of(b"cache"))).unwrap();
        let err = pins
            .check("4.0.2devnet/transaction_verifier_index.postcard", b"cache")
            .unwrap_err();
        assert!(err.to_string().contains("pins no SHA-256"), "{err}");
        // No pins at all, the build's `-`: everything is refused.
        let none = CircuitPins::parse("-").unwrap();
        assert!(none.check(FILE, b"cache").is_err());
        assert_eq!(CircuitPins::parse("").unwrap(), none);
    }

    #[test]
    fn parses_several_and_refuses_malformed_pins() {
        let value = format!(
            "{FILE}={}; 4.0.2devnet/x_gates.json={}",
            hex_of(b"a"),
            hex_of(b"b")
        );
        let pins = CircuitPins::parse(&value).unwrap();
        pins.check("4.0.2devnet/x_gates.json", b"b").unwrap();
        for bad in [
            "no-equals-sign".to_owned(),
            format!("{FILE}=abcd"),
            format!("{FILE}={}", "zz".repeat(32)),
            format!("{FILE}={};{FILE}={}", hex_of(b"a"), hex_of(b"a")),
        ] {
            assert!(CircuitPins::parse(&bad).is_err(), "{bad}");
        }
    }
}

#[cfg(all(test, not(target_family = "wasm"), feature = "embedded-circuits"))]
mod embedded_tests {
    use super::*;

    #[test]
    fn every_embedded_file_matches_ocaml_sha256() {
        let mut largest = (0, std::time::Duration::ZERO);
        for (directory, manifest) in [
            (
                "4.0.2devnet",
                include_str!("../../../../tools/mesa-circuits/devnet-blobs.sha256"),
            ),
            (
                "4.0.2mainnet",
                include_str!("../../../../tools/mesa-circuits/mainnet-blobs.sha256"),
            ),
        ] {
            assert_eq!(manifest.lines().count(), 24);
            for line in manifest.lines() {
                let (digest, name) = line.split_once("  ").unwrap();
                let path = format!("{directory}/{name}");
                let started = std::time::Instant::now();
                let bytes = fetch_native(Path::new(&path), || {
                    panic!("embedded files must not inspect local sources")
                })
                .unwrap();
                if bytes.len() > largest.0 {
                    largest = (bytes.len(), started.elapsed());
                }
                CircuitPins::parse(&format!("{path}={digest}"))
                    .unwrap()
                    .check_hosted(&path, &bytes)
                    .unwrap();
            }
        }
        eprintln!(
            "largest embedded file: {} bytes, first decode and SHA-256 check: {:.3} s",
            largest.0,
            largest.1.as_secs_f64()
        );
    }

    #[test]
    fn corrupt_embedded_payload_is_refused() {
        let circuit = embedded_circuits::get("4.0.2mainnet",
            "step-step-proving-key-transaction-snark-merge-1-f970ffc5f94017c2d8b47516c890c21f_rows_rev.bin",
        )
        .unwrap();
        let (compressed, digest) = (circuit.compressed, circuit.sha256);
        let name = "step-step-proving-key-transaction-snark-merge-1-f970ffc5f94017c2d8b47516c890c21f_rows_rev.bin";
        let mut corrupt = compressed.to_vec();
        corrupt[0] ^= 1;
        assert!(decode_embedded(&corrupt, name, digest).is_err());
        let err = decode_embedded(compressed, name, &"0".repeat(64)).unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::InvalidData);
    }

    #[test]
    fn unlisted_files_are_not_embedded() {
        assert!(fetch_embedded(Path::new("other/x_gates.json")).is_none());
        assert!(fetch_embedded(Path::new("4.0.2devnet/unknown_gates.json")).is_none());
    }
}

#[cfg(all(test, not(target_family = "wasm")))]
mod mainnet_tests {
    use super::*;

    const MERGE: &str = "4.0.2mainnet/step-step-proving-key-transaction-snark-merge-1-f970ffc5f94017c2d8b47516c890c21f_rows_rev.bin";

    #[test]
    fn unpinned_mainnet_files_cannot_fall_through() {
        for name in [
            "4.0.2mainnet/unknown_gates.json".to_owned(),
            format!("4.0.2mainnet/../{MERGE}"),
            format!("/{MERGE}"),
        ] {
            let error =
                fetch_native(Path::new(&name), || panic!("must refuse before lookup")).unwrap_err();
            assert_eq!(error.kind(), std::io::ErrorKind::InvalidData);
            assert!(error.to_string().contains("no pinned SHA-256"));
        }
        // Harmless current-directory components cannot bypass the pins.
        assert_eq!(
            mainnet_pin(Path::new(MERGE)).unwrap(),
            mainnet_pin(Path::new(&format!("./{MERGE}"))).unwrap()
        );
    }

    #[test]
    fn mainnet_lookup_matches_ocaml_manifest() {
        for line in include_str!("../../../../tools/mesa-circuits/mainnet-blobs.sha256").lines() {
            let (digest, name) = line.split_once("  ").unwrap();
            assert_eq!(
                mainnet_pin(Path::new(&format!("4.0.2mainnet/{name}"))).unwrap(),
                Some(digest)
            );
        }
    }

    #[test]
    #[cfg(not(feature = "embedded-circuits"))]
    fn mainnet_local_mismatch_and_absence_are_terminal() {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("corrupt-circuit");
        std::fs::write(&file, b"unverified circuit bytes").unwrap();
        let mismatch = fetch_native(Path::new(MERGE), || Some(file)).unwrap_err();
        assert_eq!(mismatch.kind(), std::io::ErrorKind::InvalidData);
        assert!(mismatch.to_string().contains("SHA-256"));

        let missing = fetch_native(Path::new(MERGE), || None).unwrap_err();
        assert_eq!(missing.kind(), std::io::ErrorKind::NotFound);
        assert!(missing
            .to_string()
            .contains("mainnet circuit downloads are disabled"));
    }
}

#[cfg(all(test, not(target_family = "wasm"), not(feature = "embedded-circuits")))]
mod no_embedded_tests {
    #[test]
    fn loader_still_reads_a_local_file() {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("fixture_gates.json");
        std::fs::write(&file, b"local circuit").unwrap();
        assert_eq!(super::fetch_blocking(&file).unwrap(), b"local circuit");
    }
}
